{
  "world": {
    "name": "圣辉纪元 (Era of Sanctis)",
    "cosmology": {
      "creation_myth": {
        "supreme_deity": "至高神 (Deus Omnipotens)",
        "origin": "至高神从虚无中创造了世界，以圣辉之力赐予秩序，又以混沌之火铸造挑战，构成了光与暗的永恒平衡。",
        "first_age": "圣辉纪元初始，七圣王诞生，代表七大至高秩序。",
        "cataclysm": "第一堕天之战，七灾王的诞生，深渊与圣辉永远对立。"
      },
      "universe_structure": {
        "realms": {
          "Sanctis_Celestia": {
            "name": "圣辉天界",
            "type": "神圣领域",
            "description": "至高神圣之地，由七圣王统治，光明与秩序的源头。",
            "inhabitants": ["神祇", "天使", "圣眷者"],
            "ruling_body": "七圣王 (Seven Divine Lords)",
            "laws": [
              "信仰至高神",
              "神圣秩序不可违背",
              "异端必须被净化"
            ],
            "holy_sites": [
              "神圣审判塔",
              "圣辉圣殿",
              "万神祭坛"
            ]
          },
          "Abyss_of_Perdition": {
            "name": "烬灭深渊",
            "type": "堕落与混沌的领域",
            "description": "异端、堕天使与黑暗生物的聚集地。",
            "inhabitants": ["堕落者", "恶魔", "堕天使"],
            "ruling_body": "七灾王 (Seven Lords of Perdition)",
            "key_factions": [
              "堕落军团",
              "黑暗法典会",
              "深渊信徒"
            ],
            "major_locations": [
              "无光祭坛",
              "混沌深渊裂隙",
              "七罪王座"
            ]
          },
          "Mortal_Terra": {
            "name": "人间界",
            "type": "凡人种族的生存之地",
            "description": "不同势力争夺信仰与权力的世界。",
            "inhabitants": ["人类", "精灵", "矮人", "兽人"],
            "key_factions": [
              "人类帝国",
              "精灵议会",
              "矮人王国"
            ]
          }
        }
      }
    },
    "economy": {
      "currency": {
        "Sanctis_Coin": {
          "name": "圣辉币",
          "value": 1,
          "description": "圣辉天界发行的基础货币，代表圣光的庇佑。",
          "usage": ["日常交易", "圣祈之庭交易"]
        },
        "Judgment_Credit": {
          "name": "审判币",
          "value": 100,
          "description": "由审判殿发行，仅用于特殊圣职者交易。",
          "usage": ["购买圣器", "执行神罚任务"]
        },
        "Abyss_Token": {
          "name": "深渊币",
          "value": 1,
          "description": "烬灭深渊流通的货币，主要用于黑暗交易。",
          "usage": ["堕落者交易", "黑市"]
        }
      }
    },
   "power_hierarchy": {
      "divine_ranks": {
        "Supreme_Deity": {
          "name": "至高神",
          "power_level": "无限",
          "description": "唯一的神明，创造万界的起源。"
        },
        "Seven_Divine_Lords": {
          "name": "七圣王",
          "power_level": "神级",
          "description": "圣辉天界的最高管理者，代表七大秩序。"
        },
        "Archangels": {
          "name": "大天使",
          "power_level": "高神级",
          "description": "执行神之意志的最高天使。"
        }
      },
      "mortal_ranks": {
        "Saintly_Hero": {
          "name": "圣贤",
          "power_level": "至高凡人",
          "description": "凡人中的极致存在，可与神明对话。"
        },
        "Holy_Knight": {
          "name": "圣骑士",
          "power_level": "超凡战士",
          "description": "受圣辉祝福的强大战士，能操纵圣光。"
        },
        "Priest": {
          "name": "圣职者",
          "power_level": "高级信仰者",
          "description": "掌握圣辉祈祷术，传播信仰。"
        }
      }
    },
    "resources": {
