        "Holy_Crystal": {
          "name": "圣辉水晶",
          "description": "蕴含圣光能量，可用于制造圣器。",
          "locations": ["圣辉天界", "圣祈之庭"]
        },
        "Celestial_Metal": {
          "name": "天界金属",
          "description": "极致的金属材料，能打造神圣武器。",
          "locations": ["圣辉天界"]
        }
      },
