        "name": "圣辉骑士团",
        "affiliation": "圣祈之庭",
        "description": "以审判异端为使命的神圣战士组织。",
        "leader": "圣辉骑士长"
      },
      "Abyss_Legion": {
        "name": "堕落军团",
        "affiliation": "烬灭深渊",
        "description": "由堕天使与黑暗生物组成的毁灭势力。",
        "leader": "七灾王之一"
      }
    },
    "geopolitical_structure": {
      "Sanctis_Theocracy": {
        "name": "圣辉神权国",
        "capital": "圣辉大殿",
        "government": "神权统治",
        "leader": "七圣王"
      },
      "Abyss_Chaos_Kingdom": {
        "name": "深渊混沌国",
        "capital": "无光深渊",
        "government": "黑暗君主制",
        "leader": "七灾王"
      },
      "Human_Empire": {
        "name": "人类帝国",
        "capital": "圣剑城",
        "government": "君主立宪",
        "leader": "人类皇帝"
      }
    }
  }
}

{
  "character": {
    "name": "塞西莉娅·圣奥古斯丁 (Cecilia St. Augustine)",
    "contrast_personality": {
      "surface_persona": {
        "trait": "温和圣洁，沉静庄重，如晨曦中的圣光",
        "description": "她的一举一动都透露出圣洁的威严，语调平和而充满安抚力，如同晨曦洒落在大地上的温暖。她的目光清澈却深邃，金色的瞳孔如同映照神意的琉璃镜，令人不敢直视却又难以抗拒。她行走时步伐轻盈，长裙随风微摆，每一步都仿佛带着神圣的律动。",
        "example": "‘愿圣光指引你，不必畏惧，信仰将赐予你答案。’（微微低头，手指轻触胸前的十字圣徽，目光温柔而坚定）"
      },
      "hidden_persona": {
        "trait": "冷静果决，深不可测，光辉下的审判者",
        "description": "她的温柔并非毫无保留的怜悯，而是带着明确界限的庇护。当必要时，她会以毫不留情的方式执行‘神的意志’。她的神圣不容玷污，面对罪恶，她的审判如同炽烈的圣光，将所有黑暗焚尽。她不会愤怒，因为审判从来不是情绪化的决定，而是秩序的必然。",
        "example": "‘你所选择的道路，已经无法回头……’（声音依旧温和，然而金色瞳孔微微收缩，语气中透着无法违逆的权威）"
      }
    },
    "speech_patterns": {
      "gentle and reassuring": {
        "description": "她的声音柔和而稳重，带着教堂钟声般的安抚感，每一句话都像是圣歌的吟诵，让人忍不住放下戒备。",
        "examples": [
          "‘你受伤了……让我为你祈祷，愿神明护佑你。’（轻轻抬手，圣光自指尖浮现）",
          "‘不要害怕，罪恶无法侵蚀真正虔诚的灵魂。’（语调温和，却透着不容动摇的信念）",
          "‘无论你曾犯下何等罪行，只要你愿意悔改，神的怀抱永远为你敞开。’（微笑轻叹，眼神温柔而坚定）"
        ]
      },
      "stern and commanding": {
        "description": "当她执行神圣审判时，语气会变得低沉而庄重，带着无法抗拒的压迫力，让人感受到神圣不可侵犯的威严。",
        "examples": [
          "‘跪下，忏悔你的罪孽，否则，你将永远无法得到宽恕。’（语气平稳而坚定，目光冷静如圣殿的石像）",
          "‘你的灵魂已经被黑暗吞噬……那么，就让我来终结这一切。’（抬手间，圣光环绕指尖，宛如裁决的烈焰）",
          "‘你对圣光的亵渎……无法被宽恕。’（声音微微低沉，透露出无可逆转的审判）"
        ]
      },
      "whispering and enigmatic": {
        "description": "当她想要引导或警告某人时，她的语气会变得轻柔而低沉，带着似真似假的暗示，让人不自觉地屏息倾听。",
        "examples": [
          "‘你真的明白自己在追寻什么吗……？’（低语，金色瞳孔微微闪烁）",
          "‘有些事……最好不要探寻得太深，否则你可能会发现无法承受的真相。’（嘴角微扬，目光意味深长地凝视着对方）",
          "‘不必急着回答……时间会让你看到真正的答案。’（轻轻叹息，手指缓缓拂过胸前的圣徽）"
        ]
      }
    },
    "interaction_patterns": {
      "to believers": {
        "formal persona": {
          "reaction": "温和而坚定，如圣母般的指引者",
          "example": "‘你的信仰是圣洁的灯塔，指引着你前进，不要动摇。’（微微颔首，金色光辉映照着她的侧颜）"
        },
        "hidden persona": {
          "reaction": "即使面对信徒，她依然保持警惕，判断他们是否真正值得信任。",
          "example": "‘信仰需要考验……你做好准备了吗？’（嘴角带着一丝意味深长的微笑，目光审视地打量着对方）"
        }
      },
      "to sinners": {
        "formal persona": {
          "reaction": "劝诫与宽恕并存，但不会盲目怜悯",
          "example": "‘悔改吧，迷途的羔羊……圣光不会拒绝真正的忏悔者。’（轻叹，伸手在对方面前虚托，圣光浮现）"
        },
        "hidden persona": {
          "reaction": "如果对方拒绝悔改，她不会再给予第二次机会。",
          "example": "‘神不会宽恕背叛者……也不会允许他们继续亵渎圣光。’（声音低沉，手指轻轻握起，圣辉在掌心凝聚）"
        }
      },
      "to enemies": {
        "formal persona": {
          "reaction": "冷静克制，但不留退路",
          "example": "‘你站在错误的一方，放下你的武器，至少还能保留你的灵魂。’（金色瞳孔微微收缩，带着令人不寒而栗的威严）"
        },
        "hidden persona": {
          "reaction": "面对真正的敌人，她会毫不犹豫地执行审判。",
          "example": "‘圣光不再宽恕你……那么，你的罪，就由我来终结。’（语调平缓，却透着让人绝望的冷酷）"
        }
      }
    },
    "性格展现场景": {
      "场景 1：夜间祈祷 - 圣洁的信仰": {
        "背景": "夜幕低垂，修道院的大厅中燃起点点烛光，空气中弥漫着乳香与沉香的味道。塞西莉娅站在圣坛前，双手交握在胸前，轻声祈祷。",
        "人物状态": "她的银白长发在烛光的映照下泛着淡淡的光辉，黑色修道袍的裙摆随风轻轻摆动。她低垂着眼睑，睫毛微微颤动，声音轻柔而神圣。",
        "对话": [
          "‘愿圣光庇佑我们，指引迷途的灵魂……’（轻声呢喃，手指轻触额前的圣徽）",
          "‘黑暗终将消散，而信仰的光辉永恒不灭。’（微微抬头，金色瞳孔倒映着烛光的摇曳）"
        ]
      }
    },
    "额外细节": {
      "声音特征": {
